"""Discrete-event CAN bus simulator with attack injection.

The simulator reproduces the effects that matter for intrusion detection:

* every message has its own transmit mailbox, a random phase, clock drift
  (+/-100 ppm) and scheduling jitter;
* the bus is shared: frames are serialised at the configured bit-rate and
  bit-wise arbitration lets the lowest CAN ID win, so floods really delay
  (and, when a mailbox is overwritten, drop) legitimate frames;
* attacks are generated by separate attacker nodes that compete for the bus.

Attack types (``AttackSpec.kind``):

=====================  =====================================================
``dos``                ID 0x000 every 0.3 ms (HCRL Car-Hacking style)
``fuzzy``              random ID + random payload every 0.5 ms
``spoof_rpm``          fixed RPM frame (0x316) every 1 ms
``spoof_gear``         fixed gear frame (0x43F) every 1 ms
``replay``             re-sends recorded steering frames (0x1F1)
``masquerade``         victim ECU silenced (bus-off), attacker sends 0x4B0
                       at the right period but with naive payloads
``stealth_masquerade`` as above, but the attacker keeps the rolling counter
                       and recomputes the CRC (models a reverse-engineered
                       message) - only cryptographic authentication stops it
=====================  =====================================================
"""
from __future__ import annotations

from dataclasses import dataclass, field

import numpy as np

from .checksums import compute
from .frame import ATTACK, NORMAL, CANFrame
from .vehicle import CATALOG_BY_ID, MESSAGE_CATALOG, DrivingTrace, MessageSpec, generate_trace

ATTACK_KINDS = ["dos", "fuzzy", "spoof_rpm", "spoof_gear", "replay",
                "masquerade", "stealth_masquerade"]


@dataclass
class AttackSpec:
    kind: str
    start: float
    duration: float
    params: dict = field(default_factory=dict)

    @property
    def end(self) -> float:
        return self.start + self.duration


def frame_bits(dlc: int) -> int:
    """Approximate on-wire length of a standard-ID data frame incl. IFS."""
    n = min(dlc, 8)
    stuff = (34 + 8 * n - 1) // 4 // 2   # average-case bit stuffing
    return 47 + 8 * n + stuff


def make_schedule(kind: str, duration: float, rng: np.random.Generator,
                  first: float = 8.0, length=(3.0, 5.0), gap=(6.0, 10.0)) -> list[AttackSpec]:
    """Several 3-5 s attack bursts, like the HCRL Car-Hacking captures."""
    out = []
    t = first
    while True:
        d = float(rng.uniform(*length))
        if t + d > duration - 2:
            break
        out.append(AttackSpec(kind, t, d))
        t += d + float(rng.uniform(*gap))
    return out


class CANBusSimulator:
    def __init__(self, seed: int = 0, bitrate: int = 500_000,
                 catalog: list[MessageSpec] | None = None,
                 jitter_std: float = 40e-6, drift_ppm: float = 100.0):
        self.seed = seed
        self.rng = np.random.default_rng(seed)
        self.bitrate = bitrate
        self.catalog = catalog or MESSAGE_CATALOG
        self.jitter_std = jitter_std
        self.drift_ppm = drift_ppm
        self.trace: DrivingTrace | None = None
        # vehicle-level state that persists between drives
        self.odo0 = float(self.rng.uniform(10_000, 90_000))
        self.fuel0 = float(self.rng.uniform(40, 90))
        # per-message timing parameters, fixed for this "vehicle instance"
        self._phase = {m.can_id: float(self.rng.uniform(0, m.period or 0.5)) for m in self.catalog}
        self._period = {
            m.can_id: (m.period * (1 + self.rng.uniform(-drift_ppm, drift_ppm) * 1e-6)) if m.period else None
            for m in self.catalog
        }

    # ------------------------------------------------------------------ ECUs
    def _legit_events(self, duration: float, suppress: list[tuple[int, float, float]]):
        rng = self.rng
        tr = self.trace
        ev = []
        for m in self.catalog:
            node = ("ecu", m.can_id)
            if m.period is None:  # event driven
                t = self._phase[m.can_id]
                k = 0
                while t < duration:
                    ev.append((t, m.can_id, m.encode(tr.state(t), k), node, NORMAL, ""))
                    t += float(rng.uniform(0.1, 1.0))
                    k += 1
                continue
            p = self._period[m.can_id]
            n = int((duration - self._phase[m.can_id]) / p)
            ts = self._phase[m.can_id] + np.arange(n) * p + rng.normal(0, self.jitter_std, n)
            sup = [(a, b) for cid, a, b in suppress if cid == m.can_id]
            for k, t in enumerate(ts):
                if t < 0 or t >= duration:
                    continue
                if sup and any(a <= t < b for a, b in sup):
                    continue
                ev.append((float(t), m.can_id, m.encode(tr.state(t), k), node, NORMAL, ""))
        return ev

    # --------------------------------------------------------------- attacks
    def _attack_events(self, a: AttackSpec, legit: list) -> list:
        rng = self.rng
        node = ("atk", a.kind)
        ev = []
        if a.kind == "dos":
            iv = a.params.get("interval", 0.0003)
            for t in np.arange(a.start, a.end, iv):
                ev.append((float(t), 0x000, bytes(8), node, ATTACK, a.kind))
        elif a.kind == "fuzzy":
            iv = a.params.get("interval", 0.0005)
            for t in np.arange(a.start, a.end, iv):
                cid = int(rng.integers(0, 0x800))
                ev.append((float(t), cid, bytes(rng.integers(0, 256, 8, dtype=np.uint8)), node, ATTACK, a.kind))
        elif a.kind in ("spoof_rpm", "spoof_gear"):
            iv = a.params.get("interval", 0.001)
            if a.kind == "spoof_rpm":
                cid = 0x316
                rpm = a.params.get("rpm", 6000)
                x = int(rpm * 4)
                payload = bytes((0x05, 0x21, x & 0xFF, x >> 8, 0x0F, 0x00, 0x00, 0x7F))
            else:
                cid = 0x43F
                payload = bytes((0x11, 0x45, 0x60, 0xFF, 0x6B, 0x00, 0x00, 0x00))  # "R, gear 1"
            for t in np.arange(a.start, a.end, iv):
                ev.append((float(t), cid, payload, node, ATTACK, a.kind))
        elif a.kind == "replay":
            cid = a.params.get("can_id", 0x1F1)
            lag = a.params.get("lag", 10.0)
            src = [e for e in legit if e[1] == cid and a.start - lag <= e[0] < a.end - lag]
            off = lag + float(rng.uniform(0.002, 0.008))
            for e in src:
                ev.append((e[0] + off, cid, e[2], node, ATTACK, a.kind))
        elif a.kind in ("masquerade", "stealth_masquerade"):
            cid = a.params.get("can_id", 0x4B0)
            m = CATALOG_BY_ID[cid]
            p = self._period[cid]
            factor = a.params.get("speed_factor", 0.6)
            t0 = a.start + float(rng.uniform(0, p))
            k_legit = int(round((t0 - self._phase[cid]) / p))
            last = None
            for i, t in enumerate(np.arange(t0, a.end, m.period)):
                st = dict(self.trace.state(t))
                ramp = min(1.0, (t - a.start) / 1.0)       # 1 s ramp keeps rate-of-change plausible
                st["speed"] = st["speed"] * (1 - (1 - factor) * ramp)
                if a.kind == "stealth_masquerade":
                    data = m.encode(st, k_legit + i)       # correct counter + CRC
                else:
                    # naive: take a sniffed frame, patch the speed bytes, keep counter/CRC bytes
                    if last is None:
                        last = m.encode(self.trace.state(a.start - 0.05), k_legit - 3)
                    x = int(st["speed"] * 100)
                    data = bytes((x & 0xFF, x >> 8, x & 0xFF, x >> 8)) + last[4:]
                ev.append((float(t), cid, data, node, ATTACK, a.kind))
        else:
            raise ValueError(f"unknown attack kind {a.kind!r}")
        return ev

    # ------------------------------------------------------------------- bus
    def generate(self, duration: float, attacks: list[AttackSpec] = ()) -> list[CANFrame]:
        self.trace = generate_trace(duration + 1.0, self.rng,
                                    odo0=self.odo0 + float(self.rng.uniform(0, 60)),
                                    fuel0=self.fuel0 - float(self.rng.uniform(0, 6)))
        suppress = [(a.params.get("can_id", 0x4B0), a.start, a.end) for a in attacks
                    if a.kind in ("masquerade", "stealth_masquerade")]
        legit = self._legit_events(duration, suppress)
        events = list(legit)
        for a in attacks:
            events.extend(self._attack_events(a, legit))
        events.sort(key=lambda e: e[0])
        return self._arbitrate(events, duration)

    def _arbitrate(self, events: list, duration: float) -> list[CANFrame]:
        """Serialise frames on the bus with CAN priority arbitration.

        Each node/mailbox holds one pending frame; a newer frame from the same
        mailbox overwrites an unsent older one (typical ECU behaviour).
        """
        out: list[CANFrame] = []
        pending: dict = {}
        bit = 1.0 / self.bitrate
        t_bus = 0.0
        i, n = 0, len(events)
        while i < n or pending:
            if not pending and i < n and events[i][0] > t_bus:
                t_bus = events[i][0]
            while i < n and events[i][0] <= t_bus:
                e = events[i]
                pending[e[3]] = e
                i += 1
            if not pending:
                continue
            key, e = min(pending.items(), key=lambda kv: (kv[1][1], kv[1][0]))
            del pending[key]
            t_end = t_bus + frame_bits(len(e[2])) * bit
            if t_end > duration:
                break
            out.append(CANFrame(t_end, e[1], len(e[2]), e[2], e[4], e[5]))
            t_bus = t_end
        return out


def simulate(duration: float, attack: str | None = None, seed: int = 0,
             vehicle_seed: int = 7, first_attack: float = 8.0, **kw) -> list[CANFrame]:
    """Convenience wrapper: one capture, optionally with an attack schedule.

    ``vehicle_seed`` fixes the vehicle instance (ECU phases / clock drift) so
    that training and test captures come from the *same* car, while ``seed``
    varies the drive and the attack timing.
    """
    sim = CANBusSimulator(seed=vehicle_seed, **kw)
    sim.rng = np.random.default_rng(seed)
    attacks = make_schedule(attack, duration, sim.rng, first=first_attack) if attack else []
    return sim.generate(duration, attacks)


def recompute_crc(data: bytes, algo: str = "crc8", pos: int = 7) -> bytes:
    return data[:pos] + bytes((compute(algo, data, pos),)) + data[pos + 1:]
